fn flatten_private_merge(netlist: &mut Netlist) {
    use reda::compile::topology::GateKind;
    let producers: HashMap<_,_> = netlist.gates.iter().enumerate().map(|(i,g)| (g.output.clone(),i)).collect();
    let mut uses = HashMap::<String,usize>::new();
    for gate in &netlist.gates { for input in &gate.inputs { *uses.entry(input.clone()).or_default() += 1; } }
    let mut removed = std::collections::BTreeSet::new();
    for index in 0..netlist.gates.len() {
        if netlist.gates[index].kind != GateKind::Nor(2) { continue; }
        for pin in 0..2 {
            let input=&netlist.gates[index].inputs[pin];
            let Some(&child)=producers.get(input) else { continue; };
            if netlist.gates[child].kind != GateKind::Or(2) || uses[input] != 1 || netlist.outputs.contains(input) { continue; }
            let mut inputs=netlist.gates[index].inputs.clone();
            inputs.splice(pin..=pin,netlist.gates[child].inputs.clone());
            netlist.gates[index].inputs=inputs;
            netlist.gates[index].kind=GateKind::Nor(3);
            removed.insert(child);
            break;
        }
    }
    eprintln!("expanded private Merge2 into NOR2: {}",removed.len());
    let mut index=0;
    netlist.gates.retain(|_| { let keep=!removed.contains(&index);index+=1;keep });
}

